      },
      {
        "id": "clarity",
        "status": "satisfied",
        "evidenceLines": [7, 9, 11, 114, 115, 116, 117, 118],
        "rationale": "일상적인 사용 시나리오를 1절에 선배치하고 기술 세부사항을 5절로 명확히 분리하였으며, 기술 용어 안내를 친절하게 제공하고 있습니다."
      }
    ]
  }
}
